const std = @import("std");
const config_mod = @import("../util/config.zig");
const tensor_mod = @import("../tensor/tensor.zig");
const data_mod = @import("../data/dataset.zig");
const checkpoint_mod = @import("../checkpoint/manager.zig");
const model_mod = @import("../model/model.zig");

pub const Config = config_mod.Config;
pub const Tensor = tensor_mod.Tensor;
pub const Shape = tensor_mod.Shape;

pub const EvalResults = struct {
    perplexity: f64,
    loss: f64,
    tokens: usize,
    batches: usize,
    duration_ms: u64,
};

pub const BenchmarkResult = struct {
    batch_size: usize,
    seq_len: usize,
    throughput: f64,
};

pub const Evaluator = struct {
    config: Config,
    model: model_mod.EflaModel,
    allocator: std.mem.Allocator,

    const Self = @This();

    pub fn init(
        allocator: std.mem.Allocator,
        config: Config,
        checkpoint_path: []const u8,
    ) !Self {
        var prng = std.Random.DefaultPrng.init(@as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))));
        var model = try model_mod.EflaModel.init(
            allocator,
            config.model,
            .cpu,
            0,
            prng.random(),
        );
        var mgr = try checkpoint_mod.CheckpointManager.init(allocator, checkpoint_path);
        defer mgr.deinit();
        try mgr.loadModel(&model);
        return .{
            .config = config,
            .model = model,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Self) void {
        self.model.deinit();
    }

    pub fn evaluatePerplexity(self: *Self, data_path: []const u8, max_tokens: usize) !EvalResults {
        var dataset = try data_mod.BinaryDataset.open(self.allocator, data_path);
        defer dataset.close();

        var loader = try data_mod.DataLoader.init(
            self.allocator,
            &dataset,
            1,
            self.config.data.seq_len,
            false,
            42,
        );
        defer loader.deinit();

        const start_time = std.time.nanoTimestamp();
        var total_loss: f64 = 0.0;
        var total_tokens: usize = 0;
        var batches: usize = 0;

        while (true) {
            var batch = (try loader.next()) orelse break;
            defer batch.deinit(self.allocator);

            const batch_tokens = batch.batch_size * batch.seq_len;

            if (max_tokens > 0 and total_tokens + batch_tokens > max_tokens) {
                break;
            }

            const loss = try self.computeLoss(&batch);
            total_loss += loss * @as(f64, @floatFromInt(batch_tokens));
            total_tokens += batch_tokens;
            batches += 1;

            if (max_tokens > 0 and total_tokens >= max_tokens) {
                break;
            }
        }

        const end_time = std.time.nanoTimestamp();
        const duration_ns = end_time - start_time;
        const duration_ms: u64 = if (duration_ns > 0) @intCast(@divFloor(duration_ns, 1_000_000)) else 0;

        if (total_tokens == 0) {
            return .{
                .perplexity = 0.0,
                .loss = 0.0,
                .tokens = 0,
                .batches = 0,
                .duration_ms = duration_ms,
            };
        }

        const avg_loss = total_loss / @as(f64, @floatFromInt(total_tokens));
        const perplexity = @exp(avg_loss);

        return .{
            .perplexity = perplexity,
            .loss = avg_loss,
            .tokens = total_tokens,
            .batches = batches,
            .duration_ms = duration_ms,
        };
    }

    fn computeLoss(self: *Self, batch: *const data_mod.Batch) !f64 {
        const input_tensor = try tensor_mod.Tensor.fromBuffer(
            self.allocator,
            batch.input_ids,
            &[_]usize{ batch.batch_size, batch.seq_len },
        );
        defer input_tensor.deinit(self.allocator);

        const target_tensor = try tensor_mod.Tensor.fromBuffer(
            self.allocator,
            batch.target_ids,
            &[_]usize{ batch.batch_size, batch.seq_len },
        );
        defer target_tensor.deinit(self.allocator);

        const output = try self.model.forward(input_tensor);
        defer output.deinit(self.allocator);

        const vocab_size = self.config.model.vocab_size;
        const total_tokens = batch.batch_size * batch.seq_len;
        var total_loss: f64 = 0.0;
        const output_data = output.data();

        for (0..total_tokens) |t| {
            const target = batch.target_ids[t];
            if (target >= vocab_size) {
                continue;
            }
            const offset = t * vocab_size;
            var max_logit: f32 = -std.math.inf(f32);
            for (0..vocab_size) |v| {
                const val = output_data[offset + v];
                if (val > max_logit) {
                    max_logit = val;
                }
            }
            var log_sum_exp: f64 = 0.0;
            for (0..vocab_size) |v| {
                log_sum_exp += @exp(@as(f64, output_data[offset + v]) - @as(f64, max_logit));
            }
            const log_softmax_target = @as(f64, output_data[offset + target]) - @as(f64, max_logit) - @log(log_sum_exp);
            total_loss -= log_softmax_target;
        }

        if (total_tokens == 0) {
            return 0.0;
        }

        return total_loss / @as(f64, @floatFromInt(total_tokens));
    }

    pub fn evaluateLongContext(
        self: *Self,
        data_path: []const u8,
        context_lengths: []const usize,
    ) ![]EvalResults {
        if (context_lengths.len == 0) {
            return try self.allocator.alloc(EvalResults, 0);
        }

        var results = try self.allocator.alloc(EvalResults, context_lengths.len);
        errdefer self.allocator.free(results);

        const original_seq_len = self.config.data.seq_len;

        for (context_lengths, 0..) |ctx_len, i| {
            std.log.info("Evaluating at context length {d}", .{ctx_len});
            self.config.data.seq_len = ctx_len;
            results[i] = try self.evaluatePerplexity(data_path, 0);
        }

        self.config.data.seq_len = original_seq_len;

        return results;
    }
};

pub const Generator = struct {
    config: Config,
    model: model_mod.EflaModel,
    allocator: std.mem.Allocator,
    rng: std.Random.DefaultPrng,

    const Self = @This();

    pub fn init(
        allocator: std.mem.Allocator,
        config: Config,
        checkpoint_path: []const u8,
    ) !Self {
        var prng = std.Random.DefaultPrng.init(@as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))));
        var model = try model_mod.EflaModel.init(
            allocator,
            config.model,
            .cpu,
            0,
            prng.random(),
        );
        var mgr = try checkpoint_mod.CheckpointManager.init(allocator, checkpoint_path);
        defer mgr.deinit();
        try mgr.loadModel(&model);
        return .{
            .config = config,
            .model = model,
            .allocator = allocator,
            .rng = prng,
        };
    }

    pub fn deinit(self: *Self) void {
        self.model.deinit();
    }

    pub fn generate(
        self: *Self,
        prompt: []const u8,
        max_new_tokens: usize,
        temperature: f32,
        top_p: f32,
    ) ![]const u8 {
        var prompt_tokens = try self.tokenize(prompt);
        defer self.allocator.free(prompt_tokens);

        var all_tokens = std.ArrayList(u32).init(self.allocator);
        defer all_tokens.deinit();

        try all_tokens.appendSlice(prompt_tokens);

        const vocab_size = self.config.model.vocab_size;

        for (0..max_new_tokens) |_| {
            const current_tokens = all_tokens.items;
            const seq_len = @min(current_tokens.len, self.config.data.seq_len);
            const input_start = if (current_tokens.len > seq_len) current_tokens.len - seq_len else 0;
            const input_slice = current_tokens[input_start..];

            const input_tensor = try tensor_mod.Tensor.fromBuffer(
                self.allocator,
                input_slice,
                &[_]usize{ 1, seq_len },
            );
            defer input_tensor.deinit(self.allocator);

            const output = try self.model.forward(input_tensor);
            defer output.deinit(self.allocator);

            const output_data = output.data();
            const last_pos = seq_len - 1;
            const logits_offset = last_pos * vocab_size;
            const logits = output_data[logits_offset .. logits_offset + vocab_size];

            const next_token = try self.sampleTopP(logits, temperature, top_p);
            try all_tokens.append(next_token);
        }

        const result = try self.detokenize(all_tokens.items);
        return result;
    }

    pub fn generateGreedy(
        self: *Self,
        prompt_tokens: []const u32,
        max_new_tokens: usize,
    ) ![]u32 {
        var all_tokens = std.ArrayList(u32).init(self.allocator);
        defer all_tokens.deinit();

        try all_tokens.appendSlice(prompt_tokens);

        const vocab_size = self.config.model.vocab_size;

        for (0..max_new_tokens) |_| {
            const current_tokens = all_tokens.items;
            const seq_len = @min(current_tokens.len, self.config.data.seq_len);
            const input_start = if (current_tokens.len > seq_len) current_tokens.len - seq_len else 0;
            const input_slice = current_tokens[input_start..];

            const input_tensor = try tensor_mod.Tensor.fromBuffer(
                self.allocator,
                input_slice,
                &[_]usize{ 1, seq_len },
            );
            defer input_tensor.deinit(self.allocator);

            const output = try self.model.forward(input_tensor);
            defer output.deinit(self.allocator);

            const output_data = output.data();
            const last_pos = seq_len - 1;
            const logits_offset = last_pos * vocab_size;
            const logits = output_data[logits_offset .. logits_offset + vocab_size];

            var best_token: u32 = 0;
            var best_logit: f32 = -std.math.inf(f32);
            for (0..vocab_size) |v| {
                if (logits[v] > best_logit) {
                    best_logit = logits[v];
                    best_token = @intCast(v);
                }
            }

            try all_tokens.append(best_token);
        }

        const result = try self.allocator.alloc(u32, all_tokens.items.len);
        @memcpy(result, all_tokens.items);
        return result;
    }

    pub fn sampleTopP(
        self: *Self,
        logits: []const f32,
        temperature: f32,
        top_p: f32,
    ) !u32 {
        if (logits.len == 0) {
            return 0;
        }

        const effective_temperature = if (temperature <= 0.0) 1.0 else temperature;
        const effective_top_p = if (top_p <= 0.0 or top_p > 1.0) 1.0 else top_p;
        const n = logits.len;

        var scaled = try self.allocator.alloc(f32, n);
        defer self.allocator.free(scaled);

        var indices = try self.allocator.alloc(u32, n);
        defer self.allocator.free(indices);

        for (logits, 0..) |l, i| {
            scaled[i] = l / effective_temperature;
            indices[i] = @intCast(i);
        }

        var max_val: f32 = -std.math.inf(f32);
        for (scaled) |s| {
            if (s > max_val) max_val = s;
        }

        if (!std.math.isFinite(max_val)) {
            return 0;
        }

        var sum: f64 = 0.0;
        for (scaled) |*s| {
            const shifted = s.* - max_val;
            if (std.math.isFinite(shifted)) {
                s.* = @floatCast(@exp(@as(f64, shifted)));
            } else {
                s.* = 0.0;
            }
            sum += @as(f64, s.*);
        }

        if (sum <= 0.0 or !std.math.isFinite(sum)) {
            return 0;
        }

        for (scaled) |*s| {
            s.* = @floatCast(@as(f64, s.*) / sum);
        }

        var i_idx: usize = 0;
        while (i_idx < n) : (i_idx += 1) {
            var max_idx = i_idx;
            var j_idx = i_idx + 1;
            while (j_idx < n) : (j_idx += 1) {
                if (scaled[j_idx] > scaled[max_idx]) {
                    max_idx = j_idx;
                }
            }
            if (max_idx != i_idx) {
                const tmp_s = scaled[i_idx];
                scaled[i_idx] = scaled[max_idx];
                scaled[max_idx] = tmp_s;
                const tmp_i = indices[i_idx];
                indices[i_idx] = indices[max_idx];
                indices[max_idx] = tmp_i;
            }
        }

        var nucleus_size: usize = 0;
        var cumsum: f64 = 0.0;
        for (0..n) |idx| {
            cumsum += @as(f64, scaled[idx]);
            nucleus_size = idx + 1;
            if (cumsum >= @as(f64, effective_top_p)) {
                break;
            }
        }

        if (nucleus_size == 0) {
            nucleus_size = 1;
        }

        var nucleus_sum: f64 = 0.0;
        for (0..nucleus_size) |idx| {
            nucleus_sum += @as(f64, scaled[idx]);
        }

        if (nucleus_sum <= 0.0 or !std.math.isFinite(nucleus_sum)) {
            return indices[0];
        }

        const r = self.rng.random().float(f64) * nucleus_sum;
        var running: f64 = 0.0;
        for (0..nucleus_size) |idx| {
            running += @as(f64, scaled[idx]);
            if (running >= r) {
                return indices[idx];
            }
        }

        return indices[nucleus_size - 1];
    }

    fn tokenize(self: *Self, text: []const u8) ![]u32 {
        var tokens = std.ArrayList(u32).init(self.allocator);
        defer tokens.deinit();
        for (text) |byte| {
            try tokens.append(@as(u32, byte));
        }
        const result = try self.allocator.alloc(u32, tokens.items.len);
        @memcpy(result, tokens.items);
        return result;
    }

    fn detokenize(self: *Self, tokens: []const u32) ![]const u8 {
        var output = std.ArrayList(u8).init(self.allocator);
        errdefer output.deinit();
        for (tokens) |token| {
            if (token < 256) {
                try output.append(@as(u8, @intCast(token)));
            } else {
                try output.append('?');
            }
        }
        return output.toOwnedSlice();
    }
};

pub fn benchmarkThroughput(
    allocator: std.mem.Allocator,
    config: Config,
    batch_sizes: []const usize,
    seq_lengths: []const usize,
) ![]BenchmarkResult {
    var results = std.ArrayList(BenchmarkResult).init(allocator);
    errdefer {
        results.deinit();
    }

    var prng = std.Random.DefaultPrng.init(@as(u64, @truncate(@as(u128, @bitCast(std.time.nanoTimestamp())))));

    for (batch_sizes) |batch_size| {
        for (seq_lengths) |seq_len| {
            std.log.info("Benchmarking batch_size={d}, seq_len={d}", .{ batch_size, seq_len });

            var model = try model_mod.EflaModel.init(
                allocator,
                config.model,
                .cpu,
                0,
                prng.random(),
            );
            defer model.deinit();

            const total_tokens_per_batch = batch_size * seq_len;
            var input_data = try allocator.alloc(u32, total_tokens_per_batch);
            defer allocator.free(input_data);

            for (0..total_tokens_per_batch) |idx| {
                input_data[idx] = @intCast(prng.random().intRangeAtMost(u32, 0, @as(u32, @intCast(config.model.vocab_size - 1))));
            }

            const input_tensor = try tensor_mod.Tensor.fromBuffer(
                allocator,
                input_data,
                &[_]usize{ batch_size, seq_len },
            );
            defer input_tensor.deinit(allocator);

            const warmup_iterations: usize = 2;
            for (0..warmup_iterations) |_| {
                const warmup_output = try model.forward(input_tensor);
                warmup_output.deinit(allocator);
            }

            const num_iterations: usize = 10;
            const start = std.time.nanoTimestamp();

            for (0..num_iterations) |_| {
                const output = try model.forward(input_tensor);
                output.deinit(allocator);
            }

            const end = std.time.nanoTimestamp();
            const duration_ns = end - start;

            var throughput: f64 = 0.0;
            if (duration_ns > 0) {
                const tokens_per_iter = @as(f64, @floatFromInt(total_tokens_per_batch));
                const total_tokens_processed = tokens_per_iter * @as(f64, @floatFromInt(num_iterations));
                const duration_seconds = @as(f64, @floatFromInt(duration_ns)) / 1_000_000_000.0;
                throughput = total_tokens_processed / duration_seconds;
            }

            try results.append(.{
                .batch_size = batch_size,
                .seq_len = seq_len,
                .throughput = throughput,
            });
        }
    }

    return results.toOwnedSlice();
}
